                      if (tarotCardPlacementsRefs)
                        await $_getPrefetchedData<
                          TarotReading,
                          $TarotReadingsTable,
                          TarotCardPlacement
                        >(
                          currentTable: table,
                          referencedTable: $$TarotReadingsTableReferences
                              ._tarotCardPlacementsRefsTable(db),
                          managerFromTypedResult: (p0) =>
